    audioCleanup(Runnable {
        runCatching {
            val file = File(path)
            if (file.exists() && !file.delete()) {
                log.warn("Unable to delete captured audio after terminal processing")
            }
        }.onFailure { error -> log.warn("Unable to delete captured audio: ${error.javaClass.simpleName}") }
    })
}

